async function huntOne(pattern, walkToCoord, budgetMs) {
  const end = Math.min(Date.now() + budgetMs, DEADLINE - 8000);
  if (walkToCoord) { try { await bot.walkTo(walkToCoord[0], walkToCoord[1], 6, {timeout: 40000}); } catch(e){} }
  while (Date.now() < end) {
    let npc = await findAtk(pattern);
    if (!npc) { await sdk.waitForTicks(1); continue; }
    const idx = npc.index, lvl = npc.combatLevel, nm = npc.name;
    let res;
    try { res = await bot.attack(npc); } catch(e) { await sdk.waitForTicks(1); continue; }
    if (!res.success) { await sdk.waitForTicks(1); continue; }
    const t0 = Date.now();
    while (Date.now() - t0 < 35000) {
      const s = sdk.getState();
      if (s.player.hp <= 6) { try { await bot.eatFood(); } catch(e){} }
      const still = s.nearbyNpcs.find(n => n.index === idx);
      if (!still) { recordKill(nm, lvl); return true; }
      if (!s.player.combat.inCombat) { try { await bot.attack(npc); } catch(e){} }
      await sdk.waitForTicks(1);
    }
  }
  return false;
}

